# Fallback content when service config files are unavailable
_GATEWAY_SEED_FALLBACK: dict[str, str] = {
    "profiles.yaml": "profiles: {}\n",
    "model_transformations.yaml": "transformations: {}\n",
}

# ∀ file ∈ _GATEWAY_SEED_FALLBACK: if content == fallback, file was never populated
_SERVICE_CONFIG_DIR = WORKSPACE_ROOT / "services/universal-stargate/config"


def _gateway_seed_content(name: str) -> str:
    """Return seed content for a ~/.gateway config file.

    Reads from services/universal-stargate/config/ when available so that
    profiles and transformations ship with working defaults. Falls back to
    the empty-placeholder string if the source file is missing.
    """
    source = _SERVICE_CONFIG_DIR / name
    if source.exists():
        return source.read_text()
    fallback = _GATEWAY_SEED_FALLBACK.get(name, "")
    logger.warning("Service config not found: %s — using empty fallback", source)
    return fallback


def load_env_file(path: Path) -> dict[str, str]:
    """Parse KEY=VALUE lines from an env file. Shared for TUI and headless relay."""
    entries: dict[str, str] = {}
    if not path.exists():
        return entries
    try:
        lines = path.read_text().splitlines()
    except OSError as exc:
        logger.warning("Could not read env file %s: %s", path, exc)
        return entries
    for line in lines:
        line = line.strip()
        if line.startswith("export "):
            line = line[len("export ") :]
        if line and not line.startswith("#") and "=" in line:
            key, value = line.split("=", 1)
            key = key.strip()
            if key:
                entries[key] = os.path.expandvars(value.strip())
    return entries


def build_service_env(
    workspace_root: Path, node_env_path: Path | None = None
) -> dict[str, str]:
    """Build env dict from os.environ + .env.local + secrets.env + optional node env.

    Also backfills ``MCP_PUBLIC_URL`` and ``MCP_AUTH_TOKEN`` from
    ``~/.gateway/mcp.yaml`` when missing — required by the gateway/Stargate
    container for the frontier-dispatch ``remote_mcp`` code path
    (``libs/llm_adapters/_mcp_entry.resolve_mcp_env``). Both env vars must be
    set in the ``manage`` process environment for the compose passthrough in
    ``docker/compose/unix-socket.yml`` to populate the container.
    """
    env = dict(os.environ)
    env.update(load_env_file(workspace_root / ".env.local"))
    env.update(load_env_file(GATEWAY_DIR / "secrets.env"))
    if node_env_path:
        env.update(load_env_file(node_env_path))
    cfg = load_mcp_config()
    if cfg is not None:
        if not env.get("MCP_AUTH_TOKEN") and cfg.auth_token:
            env["MCP_AUTH_TOKEN"] = cfg.auth_token
        if not env.get("MCP_PUBLIC_URL") and cfg.mcp_server_url:
            env["MCP_PUBLIC_URL"] = cfg.mcp_server_url
    return env


